out = ["# Inc 8 — test cases (E1, corrected at E3R1)", "",
       "One row per alternative of a requirement (`roles/tester.md` format: `<requirement id>/<n> | example id | test name | full or partial`), plus the objective and the class (N normal, R robustness). The **test name** and the **full / partial** mark are the tester's at E4; a case's result comes from the test run, never from this file. Expected values are the requirement's exact values; examples `EX-*` are in `codewire/graph-inc8.md` and come from `evidence-e1/pilot_inc8-transcript.txt` — a test loads or computes them and never retypes a hand count. Fixtures: DEFC (`tools/synth/make_release_case.py --case definitions`, seed 20260001), V171 (`examples/case_00_public/ASAP2_Demo_V171.a2l` with the pilot's hand image), software_a (`examples/case_00_public/software_a.a2l`). Captures are in `E1-rulings.md` §6, not here.",
       "", "Generated from `evidence-e1/cases.py` (the case list as data).", "",
       "| Case | Example | Objective — verify that … (expected) | Class | Test name (E4) | full / partial (E4) |",
       "|---|---|---|---|---|---|"]
n = nn = nr = 0
for rid, alts in C:
    for i, (ex, obj, cl) in enumerate(alts, 1):
        out.append(f"| {rid}/{i} | {ex} | {obj} | {cl} | — | — |")
        n += 1
        if cl == "N":
            nn += 1
        else:
            nr += 1
out += ["", f"**Count:** {n} cases over {len(C)} requirements ({nn} normal, {nr} robustness). The retired rows R-TUI-063.2, R-TUI-063.7 and R-PE-DEF.1 (split into .1.1 and .1.2 at E3R1) have no case."]
open(sys.argv[1], "w", encoding="utf-8", newline="\n").write("\n".join(out) + "\n")
print(n, len(C), nn, nr)
